require_once __DIR__.'/../funciones.php'; requireRole('Guardia','..');$q=trim($_GET['q']??'');$like='%'.$q.'%';
$sql="SELECT v.*,vi.nombre_completo,vi.numero_identidad FROM visitas v JOIN visitantes vi ON vi.id_visitante=v.id_visitante";
if($q!==''){$st=mysqli_prepare($conn,$sql." WHERE vi.nombre_completo LIKE ? OR vi.numero_identidad LIKE ? OR v.codigo_qr LIKE ? OR v.area_destino LIKE ? ORDER BY v.fecha_registro DESC LIMIT 300");mysqli_stmt_bind_param($st,'ssss',$like,$like,$like,$like);mysqli_stmt_execute($st);$r=mysqli_stmt_get_result($st);}else{$r=mysqli_query($conn,$sql." ORDER BY v.fecha_registro DESC LIMIT 300");}$lista=$r->fetch_all(MYSQLI_ASSOC);
$titulo='Historial';$base='..';include __DIR__.'/../header.php'; ?>
<div class="page-head"><div><h1>Historial de visitas</h1><p>Consulta por nombre, DNI, QR o área.</p></div><a class="btn ghost" href="dashboard.php">← Volver</a></div><form class="searchbar"><input name="q" value="<?=e($q)?>" placeholder="Buscar por nombre, DNI, QR o área..."><button class="btn secondary">Buscar</button></form>
